using WAID.Application.Services;namespace WAID.Infrastructure.Diagnostics;public sealed class EnvironmentSnapshotComponentProvider(string name):ISystemSnapshotComponentProvider{public string Name=>name;public string SerializerVersion=>"component-1.0";public Task<IReadOnlyDictionary<string,string>>CaptureAsync(CancellationToken token){token.ThrowIfCancellationRequested();IReadOnlyDictionary<string,string> values=Name=="hardware"?new Dictionary<string,string>{{"architecture",System.Runtime.InteropServices.RuntimeInformation.OSArchitecture.ToString()},{"logicalProcessors",Environment.ProcessorCount.ToString(System.Globalization.CultureInfo.InvariantCulture)},{"is64Bit",Environment.Is64BitOperatingSystem.ToString()}}:new Dictionary<string,string>{{"description",System.Runtime.InteropServices.RuntimeInformation.OSDescription},{"framework",System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription},{"osVersion",Environment.OSVersion.Version.ToString()}};return Task.FromResult(values);}}
